    const rcLow = () => ({ parts: [['AC', 2, 4, 1, '1V 1kHz', { l: 'G1' }], ['R', 2, 2, 0, '1k', { l: 'R1' }], ['C', 6, 2, 1, '100n', { l: 'C1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [0, 2], tempo: 0.3, win: 0.004 });
    const rcHigh = () => ({ parts: [['AC', 2, 4, 1, '1V 1kHz', { l: 'G1' }], ['C', 2, 2, 0, '10n', { l: 'C1' }], ['R', 6, 2, 1, '10k', { l: 'R1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [0, 2], tempo: 0.3, win: 0.004 });
    const lcSeries = () => ({ parts: [['AC', 2, 4, 1, '1V 1kHz', { l: 'G1' }], ['R', 2, 2, 0, '47', { l: 'R1' }], ['L', 6, 2, 0, '10m', { l: 'L1' }], ['C', 10, 2, 1, '2.5u', { l: 'C1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [10, 6, 10, 8, 2, 8]], scopes: [0, 3], tempo: 0.3, win: 0.004 });
