    const hp100 = c => ({ parts: [['AC', 2, 4, 1, '1V 1kHz', { l: 'G1' }], ['C', 2, 2, 0, c, { l: 'C1' }], ['R', 6, 2, 1, '10k', { l: 'R1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [0, 2], tempo: 0.3, win: 0.02 });
