    /* ---- Schulstoff Oszilloskop: Kästchen ablesen, Kurvenformen, Mischspannung, Phasenverschiebung (eigene Schaltungen und Zahlen) ---- */
    /* PRUEFEN P1: Das Oszilloskop hat 10 Teile waagerecht und 8 senkrecht (wie das analoge Schuloszilloskop). Die Aufgaben m30 und m31 legen 2 V pro Teil und 0,5 ms pro Teil fest und lassen Kästchen zählen. Passt die Schreibweise (Teile oder Kästchen, Ablenkkoeffizient) zum Unterricht? */
    /* PRUEFEN P5: Der Generator hat im Simulator 50 Ω Ausgangswiderstand. In den Sollwerten von m33 bis m36 steckt er in der Rechnung (Teiler 680 Ω + 270 Ω + 50 Ω = 1 kΩ, also Faktor 0,27; Tiefpass 4,7 kΩ + 50 Ω). Soll er in den Tipps genannt werden, oder rechnet der Unterricht mit idealem Generator? */
    /* PRUEFEN P3: Scheitelfaktor (Umax / Ueff): Sinus 1,41, Dreieck 1,73, Rechteck 1 (m32). Mischspannung: Ueff² = UDC² + UAC² mit UAC = Û / √2 (m34). Das Multimeter im Bereich V⎓ zeigt den Mittelwert (Gleichanteil). Passt das zur Tabelle der Kurvenformen im Unterricht (Effektivwert, Gleichrichtwert, Form- und Scheitelfaktor)? Der Formfaktor kommt bewusst noch nicht vor, weil das Oszilloskop keinen Gleichrichtwert anzeigt. */
    /* PRUEFEN P4: Phasenverschiebung φ = 360° · Δt / T am RC-Tiefpass (m35): Die Spannung am Kondensator kommt später (eilt nach), φ = arctan(2π · f · R · C). Vorzeichen und Wortwahl (nacheilen, voreilen) wie im Unterricht? */
    const GEN_RI = 50;      // Ausgangswiderstand des Funktionsgenerators im Simulator in Ω: er gehört bei allen Teilern und Filtern zur Reihenschaltung
    const mixCirc = (udc, a, defect) => ({ parts: [['AC', 2, 4, 1, a + 'V 1kHz', { l: 'G1' }], ['BAT', 2, 8, 1, String(udc), { vr: 'psu', l: 'U1' }], ['R', 2, 2, 0, '680', { l: 'R1' }], ['R', 6, 2, 1, '270', Object.assign({ l: 'R2' }, defect ? { defect } : {})], ['GND', 2, 12]], wires: [[2, 4, 2, 2], [6, 6, 6, 12, 2, 12]], scopes: [3], tempo: 0.3, win: 0.004 });
    const mixOf = () => { const g = genOf(part('G1')), u = part('U1'), r1 = part('R1'), r2 = part('R2'); const U = u ? root.MessParse(u.v, 'V') : NaN, A = r1 ? root.MessParse(r1.v, 'Ω') : NaN, B = r2 ? root.MessParse(r2.v, 'Ω') : NaN, k = B / (A + B + GEN_RI + 0.1); return { k, dc: k * U, a: k * g.a }; };
    const mixRms = m => Math.sqrt(m.dc * m.dc + m.a * m.a / 2);
    const CREST = { sin: Math.SQRT2, tri: Math.sqrt(3), sq: 1 };
    const rcPh = f => ({ parts: [['AC', 2, 4, 1, '2V ' + fmtF(f), { l: 'G1' }], ['R', 2, 2, 0, '4.7k', { l: 'R1' }], ['C', 6, 2, 1, '22n', { l: 'C1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [0, 2], tempo: 0.3, win: 3 / f });
    const phOf = () => { const g = genOf(part('G1')), r = part('R1'), c = part('C1'); return Math.atan(2 * Math.PI * g.f * (root.MessParse(r.v, 'Ω') + GEN_RI) * root.MessParse(c.v, 'F')) * 180 / Math.PI; };
    const lpDef = bad => ({ parts: [['AC', 2, 4, 1, '5V 5kHz', { l: 'G1' }], ['R', 2, 2, 0, '1k', { l: 'R1' }], ['C', 6, 2, 1, '100n', Object.assign({ l: 'C1' }, bad ? { defect: 'open' } : {})], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [0, 2], tempo: 0.3, win: 0.001 });
    let cur30 = null, cur31 = null, cur32 = null, cur33 = null, cur34 = null, cur35 = null;
    /* ---- Schulstoff Grundlagen und Messtechnik (Strommesser mit Innenwiderstand, gemischte Schaltung, Messbereich, Energie, Parallelschaltung): eigene Schaltungen und Zahlen ---- */
    /* PRUEFEN P6: m37 zeichnet den Innenwiderstand des Strommessers als eigenen Widerstand Ri = 12 Ω neben das Messgerät A1 (das im Simulator nur etwa 1 mΩ hat), wie im Beispiel „Strommesser mit Innenwiderstand“. Passt das zur Darstellung im Unterricht (oder soll der Spannungsabfall am Messwerk angegeben werden)? Gilt im Unterricht „Strommesser: Ri möglichst klein, Spannungsmesser: Ri möglichst groß“ ohne Einschränkung? */
    /* PRUEFEN P7: m40 rechnet mit einem Zeigerinstrument der Klasse 1,5 (größte Abweichung in Prozent vom Messbereichsendwert) und den Bereichen 10 V und 30 V. Die Klassen- und Bereichszahlen sind frei gewählt. Wird im Unterricht der Begriff „Klasse“ oder „Fehlergrenze in Prozent vom Endwert“ benutzt, und gilt dort die Regel, dass der Zeiger im letzten Drittel der Skala stehen soll? */
    /* PRUEFEN P8: m42 und m38 benutzen den Leitwert G = 1 / R (in mS) und die Regel „Gesamtwiderstand einer Parallelschaltung ist kleiner als der kleinste Einzelwiderstand“. Wird im Unterricht auch mit dem Leitwert gerechnet (Einheit Siemens), oder genügt R = R1 · R2 / (R1 + R2)? */
    /* PRUEFEN P9: m39 lässt R2 aus zwei Spannungsmessungen bestimmen. Der Widerstandswert steht im Schaltplan (wie bei den anderen Aufgaben mit gewürfelten Werten) und soll nicht abgelesen werden. Reicht dieser Hinweis, oder soll der Wert im Plan verdeckt werden? m41 rechnet Energie in Wh (nicht kWh) mit 8 Stunden Betrieb. Passt das zum Unterricht? */
