    const ammCirc = (U, r1, ri) => ({ parts: [PSU(U), ['R', 2, 2, 0, r1, { l: 'R1' }], ['R', 6, 2, 0, ri, { l: 'Ri' }], ['AM', 10, 2, 1, '', { l: 'A1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [10, 6, 10, 8, 2, 8]], scopes: [] });
    const MX = { U: 12, r1: 120, r2: 390, r3: 270 };      // gemischte Schaltung von m38 und mf6: R1 in Reihe zu R2 parallel R3
    const mixedCirc = defect => ({ parts: [PSU(MX.U), ['R', 2, 2, 0, String(MX.r1), { l: 'R1' }], ['R', 6, 2, 1, String(MX.r2), { l: 'R2' }], ['R', 10, 2, 1, String(MX.r3), Object.assign({ l: 'R3' }, defect ? { defect } : {})], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 2, 10, 2], [6, 6, 6, 8, 2, 8], [10, 6, 10, 8, 6, 8]], scopes: [] });
