    const par3 = () => ({ parts: [['R', 2, 2, 1, '470', { l: 'R1' }], ['R', 6, 2, 1, '680', { l: 'R2' }], ['R', 10, 2, 1, '1k', { l: 'R3' }]], wires: [[2, 2, 6, 2, 10, 2], [2, 6, 6, 6, 10, 6]], scopes: [] });
    const PAR3 = 1 / (1 / 470 + 1 / 680 + 1 / 1000);      // 217,46 Ω
    const heizCirc = () => ({ parts: [PSU(12), ['R', 2, 2, 0, '47', { l: 'R1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 2, 6, 8, 2, 8]], scopes: [] });
    /* PRUEFEN P11: m43 und m44 bilden das Drehspulmesswerk als Widerstand Rm mit dem Strommesser A1 in Reihe nach (A1 zeigt den Messwerkstrom, Vollausschlag 1 mA bzw. 2 mA). Die Messwerkdaten (1 mA/150 Ω, 2 mA/120 Ω) sind frei gewählt. Passt diese Darstellung, und werden im Unterricht die Formeln R_V = (U − U_m) / I_m und R_N = U_m / (I − I_m) benutzt (oder mit dem Erweiterungsfaktor n)? */
    /* PRUEFEN P12: m45 und m46 benutzen die Begriffe Skalenkonstante (Volt je Skalenteil), Klasse (größte Abweichung in Prozent vom Messbereichsendwert) und relativer Fehler (Abweichung geteilt durch Messwert). m47 und m48 rechnen mit 10 Teilen waagerecht und den Zeitstufen 0,1 ms und 0,5 ms pro Teil. Stimmen Begriffe und Schreibweise mit dem Unterricht überein? */
    const VM_RV = 9850, SH_RN = 5;      // m43: (10 V − 0,15 V) / 1 mA;  m44: 0,24 V / 48 mA
    const vmCirc = rv => ({ parts: [PSU(10), ['R', 2, 2, 0, rv, { l: 'RV' }], ['R', 6, 2, 0, '150', { l: 'Rm' }], ['AM', 10, 2, 1, '', { l: 'A1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [10, 6, 10, 8, 2, 8]], scopes: [] });
