        solMake: () => ({ parts: [PSU(6), ['LAMP', 2, 2, 0, '6V 0.1A', { l: 'H1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 2, 6, 8, 2, 8]], scopes: [] }),
