        solMake: () => ({ parts: [PSU(5), ['R', 2, 2, 0, '430', { l: 'R1' }], ['D', 6, 2, 1, '1N4007', { l: 'D1' }], ['GND', 2, 8]], wires: [[2, 4, 2, 2], [6, 6, 6, 8, 2, 8]], scopes: [] }),
